```cpp[]
class Solution {
   public:
    void nextPermutation(vector<int>& nums) {
        // the idea is that we have to find a critical ele such that their exists a ele in its right side which is greater than it because next permutationis always greater than previous
        int critical_point = find_critical_pos(nums);

        // edge case where arr is in descending order i.e arr is last permutation, therefore return the rev which is lowest possible order 
        if (critical_point == -1) {
            reverse(nums.begin(), nums.end());//or sort its same thing
            return;
        }
        // finding ele just greater the critical point ele to swap with
        int swapping_index = find_swapping_index(nums, critical_point);
        // swapping critical point with ele just greater than it
        swap(nums[critical_point], nums[swapping_index]);
        // sort (critical_point +1 --> end)
        sort(nums.begin() + critical_point + 1, nums.end());
    }
    int find_critical_pos(vector<int>& nums) {
        int n = nums.size();
        // initialse pos to -1 incase arr is in descending order
        int pos = -1;
        // store the index of ele which has greater ele on its right side
        for (int i = 0; i < n - 1; i++) {
            if (nums[i] < nums[i + 1]) pos = i;
        }
        return pos;
    }
    int find_swapping_index(vector<int>& nums, int critical_point) {
        int n = nums.size();
        // swapping is set to -1 to avoid garbage value
        int swapping_index = -1;
        // store the ele which is just greater than the crtical point
        for (int i = critical_point + 1; i < n; i++) {
            if (nums[i] > nums[critical_point]) swapping_index = i;
        }
        return swapping_index;
    }
};
```

